    if (isCancelled()) {
        throw new JexlException.Cancel(node);
    }
    final int numChildren = node.jjtGetNumChildren();
    JexlNode parent = node.jjtGetParent();

    Object object = null;
    StringBuilder ant = null;
    boolean antish = !(parent instanceof ASTReference);
    int v = 1;

    for (int c = 0; c < numChildren; c++) {
        JexlNode objectNode = node.jjtGetChild(c);

        if (objectNode instanceof ASTMethodNode && object == null) {
            break;
        }

        object = objectNode.jjtAccept(this, object);

        if (object != null) {
            antish = false; // disallow mixing antish variable & bean with the same root to avoid ambiguity
        } else if (antish) {
            if (ant == null) {
                JexlNode first = node.jjtGetChild(0);
                if (first instanceof ASTIdentifier && ((ASTIdentifier) first).getSymbol() < 0) {
                    ant = new StringBuilder(((ASTIdentifier) first).getName());
                } else {
                    break;
                }
            }

            for (; v <= c; ++v) {
                JexlNode child = node.jjtGetChild(v);
                if (child instanceof ASTIdentifierAccess) {
                    ant.append('.');
                    ant.append(((ASTIdentifierAccess) child).getName());
